              { q: '以下哪种做法对缓解过拟合最直接有效？', options: ['增加训练轮数', '增加模型参数量', '扩充训练数据或做数据增强', '提高学习率到极大值'], answer: 2, explain: '更多样的数据能让模型学到更一般的规律，是最根本的解法。增加轮数和参数量通常会加剧过拟合。' }
