              { q: '特征之间存在严重共线性时，最可能出现什么现象？', options: ['模型完全无法训练', '系数估计不稳定，甚至符号反常', '准确率必然为 0', '特征数量自动减少'], answer: 1, explain: '共线特征提供重复信息，权重可以在它们之间大幅转移，导致系数方差变大、解释困难。' }
