              { q: 'ReLU 相比 Sigmoid 在深层网络中的主要优势是？', options: ['输出范围更大', '缓解梯度消失，计算更简单', '参数量更少', '不需要反向传播'], answer: 1, explain: 'Sigmoid 在饱和区导数接近 0，梯度逐层衰减；ReLU 在正区间导数为 1，梯度可以更稳定地传回去。' }
