              { q: '训练损失突然变为 NaN，最先应该排查什么？', options: ['数据量是否足够', '学习率是否过大或存在数值溢出', '模型层数是否太少', '是否使用了 GPU'], answer: 1, explain: '学习率过大会让参数更新跨过最优区域导致数值爆炸，也可能出现 log(0) 等情况，先降学习率并检查数据。' }
