                '③ 向量化：用 embedding 模型把文本块转成向量并入库。',
                '④ 检索 + 重排：先向量召回 Top-K，再用重排模型精排。',
                '⑤ 拼装：把命中的片段塞进提示词，要求模型「仅依据材料回答」。'
