              { q: '以下哪项最能减少 RAG 的编造行为？', options: ['提高 temperature', '要求模型仅依据给定材料回答，无依据时明确说明', '增大 max_tokens', '去掉引用'], answer: 1, explain: '通过提示约束把生成锚定在材料上，并允许「不知道」，能显著降低无依据的编造。' }
