              { q: '以下哪种情况最适合自部署模型？', options: ['刚立项验证想法', '流量极小且波动大', '数据敏感且流量稳定规模较大', '只需要一次离线分析'], answer: 2, explain: '自部署前期投入高，只有流量稳定到能摊薄 GPU 成本，且数据合规要求高时，才比 API 更划算。' }
