              { h: '顺序的隐性影响', p: '模型对靠近输入末尾的示例更敏感，也会受示例标签分布影响（例如示例里正例过多，模型更倾向判为正）。因此示例要均衡，且把最关键的示例放在最后。' },
              { warn: '示例里如果有错误标注，模型会稳定地学会错误。示例必须经过人工校验。' }
