              { q: '如果示例中正例占绝大多数，可能导致模型？', options: ['完全无法分类', '更倾向于把新样本判为正例', '输出格式改变', '拒绝回答'], answer: 1, explain: '示例的标签分布会形成隐式的先验，模型会模仿这种倾向，造成系统性偏差。' }
