              { q: '使用思维链的主要代价是？', options: ['准确率下降', '输出 token 增加，延迟与成本上升', '无法处理中文', '必须微调模型'], answer: 1, explain: '把推理过程写出来意味着更长的输出，而输出 token 是延迟和成本的主要来源。' }
