              { h: '评估维度', list: [
                '正确性：事实与结论是否成立。',
                '格式合规：结构、字段、长度是否符合规范。',
                '稳定性：同一输入多次运行结果是否一致。',
                '成本与延迟：token 数与响应时间。'
              ] },
              { tip: 'A/B 测试要限定单一变量，并保证样本量足够。用 5 条样本得出的「显著提升」通常只是噪声。' }
