              { q: '容错率极低的任务，产品设计上更应该？', options: ['追求完全自动、去掉人工', '内建人工复核与确认环节', '提高 temperature 增加多样性', '缩短提示词'], answer: 1, explain: '当错误代价很高时，AI 应定位为辅助，最终判断必须由人完成，系统需要提供便捷的核验路径。' }
