            quiz: [
              { q: 'AI 功能的最小闭环中，「兜底策略」的作用是？', options: ['提升模型准确率', '在调用失败或输出异常时保证产品仍可用', '减少 token 消耗', '加快训练速度'], answer: 1, explain: '模型调用可能超时、限流或返回不可解析内容，兜底能让用户得到合理反馈而不是报错页面。' },
              { q: '把模型 API Key 放在前端代码中会有什么后果？', options: ['没有影响', '密钥可被任何人提取并盗用，产生费用或数据风险', '提升响应速度', '降低延迟'], answer: 1, explain: '前端代码对用户完全可见，密钥一旦泄露会被批量滥用，必须由服务端代理调用。' }
            ]
