              { q: 'Agent 出现死循环时，最直接的工程手段是？', options: ['提高 temperature', '设置最大执行步数与重复调用检测', '增加工具数量', '换更大的模型'], answer: 1, explain: '硬性的步数上限与重复动作检测能强制终止异常循环，避免资源浪费与副作用累积。' }
