              { q: '为什么工具的 description 要写得像「新人上手文档」？', options: ['方便人类开发者阅读', '模型完全依据描述文字来理解工具并决定如何调用', '提高接口响应速度', '为了通过代码审查'], answer: 1, explain: '模型看不到工具的内部实现，只能看到名称、描述与参数说明。描述含糊，调用就会含糊。' }
