              { q: '以下哪种情况不需要引入 MCP？', options: ['想让多个 AI 应用共用你写的工具', '想接入社区现成的 GitHub 工具', '只给自己的 App 写一个内部查询函数', '想让工具与模型解耦维护'], answer: 2, explain: '只在单一应用内部使用的函数，用应用自带的 Function Calling 直接实现即可，引入协议层纯属多余。' }
