              { h: '三种角色', list: [
                'Host：AI 应用本体（如 IDE、聊天客户端），负责与模型交互和整体编排。',
                'Client：Host 内部的连接器，与某个 Server 保持一对一通信。',
                'Server：对外暴露能力的轻量程序，如「GitHub Server」「数据库 Server」，通过 stdio 或 HTTP 提供服务。'
              ] },
              { h: '三大原语', list: [
                'Tools（工具）：模型可主动调用的操作，如查数据、写文件——由模型决定何时调用。',
                'Resources（资源）：供读取的上下文数据，如文件内容、API 响应——由应用决定注入什么。',
                'Prompts（提示模板）：预置的提示词，由用户主动触发选用。'
              ] },
              { h: '一次调用的完整链路', p: '用户提问→Host 判断要用哪个 Server 的能力→Client 通过 stdio 或 Streamable HTTP 发送 JSON-RPC 2.0 请求→Server 执行并返回结果→Host 把结果回填给模型继续推理。所有通信都是标准化的 JSON-RPC 消息，这也是「任何客户端都能连任何 Server」的技术基础。' },
              { warn: 'MCP Server 拥有它所声明能力的全部权限。安装一个第三方 Server 前想清楚三件事：它要读什么、写什么、联网到哪里。' }
