              { q: 'EU AI Act 的「高风险」类别意味着？', options: ['直接禁止', '允许提供但承担重义务：风险管理、数据治理、人类监督、日志留存等', '只需提示用户', '自愿合规'], answer: 1, explain: '四级里只有「不可接受风险」被禁止；高风险是「可做但义务重」，如招聘筛选、信贷评估类 AI。' }
