              { h: '第二步：分步重构', list: [
                '每次只做一种变换：先提取函数，再消除重复，最后整理命名。每步跑测试并 commit。',
                '给 AI 的指令带硬约束：「不许改变任何行为、不许修改公共接口、不引入新依赖」。',
                'AI 提议的「顺手优化」一律先拒绝，记录下来重构完再单独评估。'
              ] },
              { h: '第三步：对拍验收', list: [
                '重构完成后用快照逐例对拍：输入相同、输出必须逐字节相同。',
                '重点抽查边界：空输入、超长输入、非法字符——AI 最容易在这里悄悄改变行为。',
                '完成标准：快照全绿 + 行数下降 + 零新增依赖。三条缺一不可。'
              ] },
              { warn: 'AI 最危险的重构行为是「重写成一套完全不同的实现」——测试碰巧能过、语义已变。特征测试（对拍真实输入输出）是把它按在原地的缰绳。' }
