/* ============================================================
 * 索引与工具
 * ============================================================ */
const CATEGORY_MAP = Object.fromEntries(CATEGORIES.map(c => [c.id, c]));

/* 扁平化所有课时 */
const ALL_LESSONS = [];
COURSES.forEach(course => {
  const cat = CATEGORY_MAP[course.cat];
  course.chapters.forEach((ch, ci) => {
    ch.lessons.forEach((ls, li) => {
      ALL_LESSONS.push({
        ...ls,
        courseSlug: course.slug,
        courseTitle: course.title,
        courseLevel: course.level,
        cat: course.cat,
        catName: cat ? cat.name : '',
        catColor: cat ? cat.color : '#4f46e5',
        chapterIndex: ci,
        chapterTitle: ch.title,
        lessonIndex: li,
        order: ALL_LESSONS.length
      });
    });
  });
});

const LESSON_MAP = Object.fromEntries(ALL_LESSONS.map(l => [l.id, l]));
const COURSE_MAP = Object.fromEntries(COURSES.map(c => [c.slug, c]));

const TOTAL_LESSONS = ALL_LESSONS.length;
const TOTAL_MINS = ALL_LESSONS.reduce((a, l) => a + l.mins, 0);
const TOTAL_QUIZ = ALL_LESSONS.reduce((a, l) => a + l.quiz.length, 0);

/* 每个分类的课程与课时数 */
CATEGORIES.forEach(c => {
  const cs = COURSES.filter(x => x.cat === c.id);
  c.courses = cs.length;
  c.lessons = cs.reduce((a, x) => a + x.chapters.reduce((b, ch) => b + ch.lessons.length, 0), 0);
});

/* 课程课时数与总时长 */
COURSES.forEach((c, i) => {
  c.no = 'C' + String(i + 1).padStart(2, '0');
  c.lessonCount = c.chapters.reduce((a, ch) => a + ch.lessons.length, 0);
  c.mins = c.chapters.reduce((a, ch) => a + ch.lessons.reduce((b, l) => b + l.mins, 0), 0);
  c.hours = (c.mins / 60).toFixed(1);
});

/* 课程内课时的前后关系 */
function getCourseLessons(slug) {
  return ALL_LESSONS.filter(l => l.courseSlug === slug);
}
function getAdjacent(slug, lessonId) {
  const list = getCourseLessons(slug);
  const i = list.findIndex(l => l.id === lessonId);
  return { prev: i > 0 ? list[i - 1] : null, next: i >= 0 && i < list.length - 1 ? list[i + 1] : null };
}

